def solve(value):
    """Return integer leaves left-to-right without modifying input lists."""
    result = []
    stack = [iter(value)]

    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue

        if isinstance(item, list):
            stack.append(iter(item))
        else:
            result.append(item)

    return result
